#include "ctl_dl_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void ctl_dl_defer_timeout_fnc(void * arg)
{
	// It's time to lock/unlock, if the required conditions are met

	if ((ctl_dl_cond_gwr == GWR_DONT_CARE || ctl_dl_flag_gwr == ctl_dl_cond_gwr) && 
		(ctl_dl_cond_ign == IGN_DONT_CARE || ctl_dl_flag_ign == ctl_dl_cond_ign))
	{
		cmd_q_insert(ctl_dl_action == CTL_DL_ACTION_LOCK ? (Cmd_List)(INPUT_LOCK1 | INPUT_ON): (Cmd_List)(INPUT_UNLOCK_ALL1 | INPUT_ON), COMMAND_INSERT_TIMEOUT);
	}
}

